left = [("u1", "A"), ("u2", "B"), ("u3", "C")]
right = [("u1", 10), ("u1", 20), ("u2", 30)]   # u1 appears twice

index = {}
for k, v in right:
    index.setdefault(k, []).append(v)

def left_join(validate=False):
    out = []
    for k, name in left:
        matches = index.get(k, [None])        # no match -> keep row with None
        if validate and len(matches) > 1:
            raise ValueError("not many_to_one: duplicate key " + k)
        for m in matches:
            out.append((k, name, m))
    return out

res = left_join()
print("left rows:", len(left), "result rows:", len(res))
for r in res:
    print(r)

try:
    left_join(validate=True)
except ValueError as e:
    print("validate caught:", e)

long = [("mon", "A", 5), ("mon", "B", 7), ("tue", "A", 6),
        ("tue", "A", 4), ("tue", "B", 1)]   # tue/A appears twice
print("long:", long)

# pivot needs unique (index, column) pairs
def pivot(rows):
    table = {}
    for day, store, v in rows:
        if store in table.setdefault(day, {}):
            raise ValueError("duplicate entries for " + day + "/" + store)
        table[day][store] = v
    return table

try:
    pivot(long)
except ValueError as e:
    print("pivot fails:", e)

# pivot_table aggregates duplicates (here: sum)
pt = {}
for day, store, v in long:
    pt.setdefault(day, {})
    pt[day][store] = pt[day].get(store, 0) + v
print("pivot_table sum:", pt)

# melt: wide back to long
melted = [(d, s, v) for d, row in pt.items() for s, v in row.items()]
print("melt:", melted)
